ga_M(){return"\u0417\u0430\u0433\u043b\u0443\u0448\u0438\u0442\u044c"},
ga_Y(){return"\u0412\u043a\u043b\u044e\u0447\u0438\u0442\u044c \u0437\u0432\u0443\u043a"},
